  async login(dto: AdminLoginDto & { totp?: string }): Promise<{ token: string; admin: any }> {
    const admin = await this.prisma.admin.findUnique({ where: { username: dto.username } });
    if (!admin || !(await bcrypt.compare(dto.password, admin.passwordHash))) {
      throw new UnauthorizedException('Invalid credentials');
    }
    // Second factor (TOTP) — only if enabled for this admin
    if (admin.totpEnabled && admin.totpSecret) {
      const code = (dto.totp || '').replace(/\s/g, '');
      if (!code) {
        // Password OK but 2FA code missing — signal the front to ask for it
        throw new UnauthorizedException('2FA_REQUIRED');
      }
      if (!authenticator.verify({ token: code, secret: admin.totpSecret })) {
        throw new UnauthorizedException('Code 2FA invalide');
      }
    }
    await this.prisma.admin.update({ where: { id: admin.id }, data: { lastLogin: new Date() } });
    const token = await this.jwt.signAsync(
      { adminId: admin.id, username: admin.username, role: admin.role },
      { secret: this.config.get<string>('jwt.secret'), expiresIn: '8h' },
    );
    this.logger.log(`Admin login: ${admin.username}`);
    return { token, admin: { id: admin.id, username: admin.username, role: admin.role } };
  }

  async createAdmin(dto: CreateAdminDto): Promise<any> {
    const passwordHash = await bcrypt.hash(dto.password, 12);
    return this.prisma.admin.create({
      data: { username: dto.username, passwordHash, role: dto.role || 'ADMIN' },
      select: { id: true, username: true, role: true, createdAt: true },
    });
  }

  async changeAdminPassword(adminId: string, currentPassword: string, newPassword: string): Promise<void> {
    const admin = await this.prisma.admin.findUnique({ where: { id: adminId } });
    if (!admin || !(await bcrypt.compare(currentPassword, admin.passwordHash))) {
      throw new UnauthorizedException('Mot de passe actuel incorrect');
    }
    const passwordHash = await bcrypt.hash(newPassword, 12);
    await this.prisma.admin.update({ where: { id: adminId }, data: { passwordHash } });
    this.logger.log(`Admin password changed: ${admin.username}`);
  }

  // ── 2FA (TOTP) ──
  private readonly TOTP_ISSUER = 'FTN Dashboard';

  async get2faStatus(adminId: string): Promise<{ enabled: boolean }> {
    const admin = await this.prisma.admin.findUnique({ where: { id: adminId } });
    if (!admin) throw new NotFoundException('Admin introuvable');
    return { enabled: admin.totpEnabled };
  }

  /** Generate a fresh secret + QR code. Stored but NOT yet enabled (needs verify). */
  async setup2fa(adminId: string): Promise<{ secret: string; otpauth: string; qr: string }> {
    const admin = await this.prisma.admin.findUnique({ where: { id: adminId } });
    if (!admin) throw new NotFoundException('Admin introuvable');
    if (admin.totpEnabled) throw new BadRequestException('La 2FA est déjà activée');

    const secret = authenticator.generateSecret();
    const otpauth = authenticator.keyuri(admin.username, this.TOTP_ISSUER, secret);
    const qr = await QRCode.toDataURL(otpauth);

    // Persist the pending secret (overwrites any previous pending one)
    await this.prisma.admin.update({ where: { id: adminId }, data: { totpSecret: secret } });
    return { secret, otpauth, qr };
  }

  /** Confirm the code from the authenticator app and turn 2FA on. */
  async enable2fa(adminId: string, code: string): Promise<{ enabled: boolean }> {
    const admin = await this.prisma.admin.findUnique({ where: { id: adminId } });
    if (!admin) throw new NotFoundException('Admin introuvable');
    if (admin.totpEnabled) throw new BadRequestException('La 2FA est déjà activée');
    if (!admin.totpSecret) throw new BadRequestException("Aucune configuration 2FA en cours — relancez l'activation");

    const token = (code || '').replace(/\s/g, '');
    if (!authenticator.verify({ token, secret: admin.totpSecret })) {
      throw new UnauthorizedException('Code invalide');
    }
    await this.prisma.admin.update({ where: { id: adminId }, data: { totpEnabled: true } });
    this.logger.log(`2FA enabled: ${admin.username}`);
    return { enabled: true };
  }

  /** Disable 2FA — requires current password + a valid code. */
  async disable2fa(adminId: string, password: string, code: string): Promise<{ enabled: boolean }> {
    const admin = await this.prisma.admin.findUnique({ where: { id: adminId } });
    if (!admin) throw new NotFoundException('Admin introuvable');
    if (!(await bcrypt.compare(password, admin.passwordHash))) {
      throw new UnauthorizedException('Mot de passe incorrect');
    }
    if (admin.totpEnabled && admin.totpSecret) {
      const token = (code || '').replace(/\s/g, '');
      if (!authenticator.verify({ token, secret: admin.totpSecret })) {
        throw new UnauthorizedException('Code 2FA invalide');
      }
    }
    await this.prisma.admin.update({ where: { id: adminId }, data: { totpEnabled: false, totpSecret: null } });
    this.logger.log(`2FA disabled: ${admin.username}`);
    return { enabled: false };
  }

