  async getBotConfig() {
    const raw = await this.redis.get(BOT_CONFIG_KEY);
    if (!raw) return DEFAULT_BOT_CONFIG;
    try { return { ...DEFAULT_BOT_CONFIG, ...JSON.parse(raw) }; } catch { return DEFAULT_BOT_CONFIG; }
  }

  async updateBotConfig(config: Partial<typeof DEFAULT_BOT_CONFIG>) {
    const current = await this.getBotConfig();
    const updated = { ...current, ...config };
    await this.redis.set(BOT_CONFIG_KEY, JSON.stringify(updated));
    this.logger.log('Bot config updated');
    return updated;
  }

  async getUpdateTemplates(): Promise<Record<string, any>> {
    const raw = await this.redis.get(UPDATE_TEMPLATES_KEY);
    return raw ? JSON.parse(raw) : {};
  }

  async saveUpdateTemplate(id: string | undefined, dto: {
    name: string;
    channelId: string;
    color?: string;
    authorName?: string;
    authorIconUrl?: string;
    authorUrl?: string;
    title?: string;
    url?: string;
    message?: string;
    fields?: { name: string; value: string; inline?: boolean }[];
    thumbnailUrl?: string;
    imageUrl?: string;
    footerText?: string;
    footerIconUrl?: string;
    showTimestamp?: boolean;
    mentionEveryone?: boolean;
  }): Promise<any> {
    const current = await this.getUpdateTemplates();
    const templateId = id && current[id] ? id : crypto.randomUUID();
    current[templateId] = {
      name:            dto.name,
      channelId:       dto.channelId,
      color:           dto.color || '',
      authorName:      dto.authorName || '',
      authorIconUrl:   dto.authorIconUrl || '',
      authorUrl:       dto.authorUrl || '',
      title:           dto.title || '',
      url:             dto.url || '',
      message:         dto.message || '',
      fields:          Array.isArray(dto.fields) ? dto.fields : [],
      thumbnailUrl:    dto.thumbnailUrl || '',
      imageUrl:        dto.imageUrl || '',
      footerText:      dto.footerText || '',
      footerIconUrl:   dto.footerIconUrl || '',
      showTimestamp:   dto.showTimestamp ?? true,
      mentionEveryone: dto.mentionEveryone ?? true,
      updatedAt:       new Date().toISOString(),
    };
    await this.redis.set(UPDATE_TEMPLATES_KEY, JSON.stringify(current));
    return { id: templateId, ...current[templateId] };
  }

  async deleteUpdateTemplate(id: string): Promise<{ deleted: string }> {
    const current = await this.getUpdateTemplates();
    if (!current[id]) throw new NotFoundException(`Modèle "${id}" introuvable`);
    delete current[id];
    await this.redis.set(UPDATE_TEMPLATES_KEY, JSON.stringify(current));
    return { deleted: id };
  }

