  // ── Servers ──
  private readonly SERVERS_KEY = 'admin:servers';
  private readonly DEFAULT_SERVERS = [
    { id: 'ng',      name: 'NationsGlory', description: '1.8 PvP — modules combat, mobilité, visuel', color: '#3b82f6', active: true, product: 'NG_LOADER' },
    { id: 'menoria', name: 'Menoria',       description: 'Minecraft PvP — 30+ modules dédiés',         color: '#f97316', active: true, product: 'MENORIA'   },
  ];

  async getServers(): Promise<any[]> {
    const raw = await this.redis.get(this.SERVERS_KEY);
    if (!raw) return this.DEFAULT_SERVERS;
    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) && parsed.length > 0 ? parsed : this.DEFAULT_SERVERS;
    } catch { return this.DEFAULT_SERVERS; }
  }

  async saveServers(servers: any[]): Promise<void> {
    await this.redis.set(this.SERVERS_KEY, JSON.stringify(servers));
  }

  async createServer(dto: { id: string; name: string; description: string; color: string; product: string }): Promise<any> {
    const servers = await this.getServers();
    if (servers.find(s => s.id === dto.id)) throw new BadRequestException(`Server "${dto.id}" already exists`);
    const server = { ...dto, active: true };
    servers.push(server);
    await this.saveServers(servers);
    return server;
  }

  async updateServer(id: string, dto: Partial<{ name: string; description: string; color: string; active: boolean; product: string }>): Promise<any> {
    const servers = await this.getServers();
    const idx = servers.findIndex(s => s.id === id);
    if (idx === -1) throw new NotFoundException(`Server "${id}" not found`);
    servers[idx] = { ...servers[idx], ...dto };
    await this.saveServers(servers);
    return servers[idx];
  }

  async deleteServer(id: string): Promise<void> {
    const servers = await this.getServers();
    await this.saveServers(servers.filter(s => s.id !== id));
  }

