  private readonly PROMO_CODES_KEY = 'admin:promo_codes';

  async getPromoCodes(): Promise<Record<string, any>> {
    const raw = await this.redis.get(this.PROMO_CODES_KEY);
    return raw ? JSON.parse(raw) : {};
  }

  async createPromoCode(dto: {
    code: string;
    type: 'percent' | 'fixed';
    amount: number;
    maxUses?: number;
    stripeId?: string;
  }): Promise<any> {
    const code = dto.code.toUpperCase().trim();
    if (!code || !/^[A-Z0-9_-]{2,20}$/.test(code)) {
      throw new BadRequestException('Code invalide (2ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ20 caractÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¨res alphanumÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©riques)');
    }
    const current = await this.getPromoCodes();
    if (current[code]) throw new BadRequestException(`Code "${code}" existe dÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©jÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â `);
    current[code] = {
      type: dto.type,
      amount: dto.amount,
      maxUses: dto.maxUses || 0,
      uses: 0,
      active: true,
      stripeId: dto.stripeId || '',
      createdAt: new Date().toISOString(),
    };
    await this.redis.set(this.PROMO_CODES_KEY, JSON.stringify(current));
    this.logger.log(`Promo code created: ${code}`);
    return { code, ...current[code] };
  }

  async deletePromoCode(code: string): Promise<{ deleted: string }> {
    const current = await this.getPromoCodes();
    const key = code.toUpperCase();
    if (!current[key]) throw new NotFoundException(`Code "${key}" introuvable`);
    delete current[key];
    await this.redis.set(this.PROMO_CODES_KEY, JSON.stringify(current));
    return { deleted: key };
  }

  async togglePromoCode(code: string, active: boolean): Promise<any> {
    const current = await this.getPromoCodes();
    const key = code.toUpperCase();
    if (!current[key]) throw new NotFoundException(`Code "${key}" introuvable`);
    current[key].active = active;
    await this.redis.set(this.PROMO_CODES_KEY, JSON.stringify(current));
    return { code: key, active };
  }

